public static <T extends IFactionPlayer<T> & ISkillPlayer<T>> void handleToggleActionPacket(ServerboundToggleActionPacket msg, IPayloadContext context) {
        context.enqueueWork(() -> {
            Player player = context.player();
            IActionHandler.<T>get(player).ifPresent(handler -> {
                IAction.ActivationContext activationContext = msg.target() != null ? msg.target().map(entityId -> {
                    Entity e = player.level().getEntity(entityId);
                    if (e == null) {
                        LOGGER.warn("Could not find entity {} the player was looking at when toggling action", entityId);
                    }
                    return new ActionHandler.ActivationContext(e);
                }, ActionHandler.ActivationContext::new) : new ActionHandler.ActivationContext();

                Holder<? extends IAction<?>> action = msg.action();
                if (action != null) {
                    @SuppressWarnings("unchecked")
                    IActionResult r = handler.toggleAction((Holder<IAction<T>>) (Object) action, activationContext);
                    if (!r.successful()) {
                        if (r.sendToStatusBar()) {
                            player.sendOverlayMessage(r.message());
                        } else {
                            player.sendSystemMessage(r.message());
                        }
                    } else {
                        handler.sync();
                    }
                }
            });
        });
    }

@Override
    public IActionResult toggleAction(Holder<? extends IAction<T>> action, IAction.ActivationContext context) {
        if (ActionHelper.checkActionDisableEffect(this.player)) return IActionResult.DISABLED_EFFECT;
        if (activeTimers.containsKey(action)) {
            // it must be a lasting action because it is in the activeTimers field
            deactivateAction(SafeCast.<Holder<ILastingAction<T>>>cast(action));
            return IActionResult.SUCCESS;
        } else if (cooldownTimers.containsKey(action)) {
            return IActionResult.ON_COOLDOWN;
        } else {
            if (this.player.asEntity().isSpectator()) return IActionResult.RESTRICTED;
            if (!isActionUnlocked(action)) return IActionResult.NOT_UNLOCKED;
            if (!isActionAllowedPermission(action)) return IActionResult.DISALLOWED_PERMISSION;

            IActionResult r = checkDefaultToggleConditions(action);
            if (r.successful()) {

                var mutualExclusiveActions = action.value().mutualExclusiveActionTag();
                if (mutualExclusiveActions != null) {
                    deactivateActions(mutualExclusiveActions);
                }

                /* Only lasting actions have a duration, so regular actions will return a duration of -1. */
                int duration = action.value() instanceof ILastingAction<T> lasting ? lasting.getDuration(player) : -1;
                ActionEvent.ActionActivatedEvent<T> activationEvent = FactionEventFactory.fireActionActivatedEvent(player, action, action.value().getCooldown(player), duration);
                if (activationEvent.isCanceled()) return IActionResult.fail(activationEvent.getCancelMessage());
                r = action.value().onActivated(player, context);
                if (r.successful()) {
                    player.asEntity().awardStat(FactionStats.ACTION_USED.get().get(action.value()));
                    //Even though lasting actions do not activate their cooldown until they deactivate
                    //we probably want to keep this here so that they are edited by one event.
                    int cooldown = activationEvent.getCooldown();
                    expectedCooldownTimes.put(action, cooldown);
                    if (action.value() instanceof ILastingAction) {
                        expectedDurations.put(action, activationEvent.getDuration());
                        duration = activationEvent.getDuration();
                        //noinspection unchecked
                        activeTimers.put((Holder<ILastingAction<T>>) action, duration);
                    } else {
                        cooldownTimers.put(action, cooldown);
                    }

                    if (player instanceof ServerPlayer serverPlayer) {
                        FactionAdvancements.ACTION_TRIGGER.get().trigger(serverPlayer, action);
                    }
                }
            }
            return r;
        }
    }

public void updateActions() {
        //First update cooldown timers so active actions that become deactivated are not ticked.
        for (Iterator<Object2IntMap.Entry<Holder<? extends IAction<T>>>> it = cooldownTimers.object2IntEntrySet().iterator(); it.hasNext(); ) {
            Object2IntMap.Entry<Holder<? extends IAction<T>>> entry = it.next();
            int value = entry.getIntValue();
            player.asEntity().awardStat(FactionStats.ACTION_COOLDOWN_TIME.get().get(entry.getKey().value()));
            if (value <= 1) { //<= Just in case we have missed something
                expectedCooldownTimes.removeInt(entry);
                it.remove();
            } else {
                entry.setValue(value - 1);
            }
        }

        List<Holder<? extends ILastingAction<T>>> toRemove = new ArrayList<>();
        for (Object2IntMap.Entry<Holder<? extends ILastingAction<T>>> entry : activeTimers.object2IntEntrySet()) {
            int newtimer = entry.getIntValue() - 1;

            if (newtimer == 0) {
                toRemove.add(entry.getKey());
            } else {
                Holder<? extends ILastingAction<T>> action = entry.getKey();
                ActionEvent.ActionUpdateEvent<T> event = FactionEventFactory.fireActionUpdateEvent(player, action, newtimer);
                int expectedDuration = expectedDurations.getInt(action);
                if ((!event.shouldSkipActionUpdate() && action.value().onUpdate(player, expectedDuration - newtimer, expectedDuration)) || event.shouldDeactivation()) {
                    entry.setValue(1); //Value of means they are deactivated next tick and onUpdate is not called again
                } else {
                    player.asEntity().awardStat(FactionStats.ACTION_TIME.get().get(action.value()));
                    entry.setValue(newtimer);
                }
            }
        }
        toRemove.forEach(holder -> {
            deactivateAction(holder, true);
            cooldownTimers.put(holder, expectedCooldownTimes.getInt(holder));
        });
        sync();
    }

@Override
    public boolean isActionUnlocked(Holder<? extends IAction<T>> action) {
        return this.unlockedActions.contains(action);
    }

private boolean isActionAllowedPermission(Holder<? extends IAction<T>> action) {
        if (player.asEntity() instanceof ServerPlayer serverPlayer) {
            return Permissions.ACTION.isAllowed(serverPlayer, action.value());
        }
        return true;
    }

public IActionResult checkDefaultToggleConditions(Holder<? extends IAction<T>> action) {
        if (this.player.asEntity().isSpectator()) return IActionResult.RESTRICTED;
        if (!isActionUnlocked(action)) return IActionResult.NOT_UNLOCKED;
        if (!isActionAllowedPermission(action)) return IActionResult.DISALLOWED_PERMISSION;

        return action.value().canUse(player);
    }

public void deactivateAction(Holder<? extends ILastingAction<T>> action, boolean ignoreCooldown) {
        deactivateAction(action, false, false);
    }

@Override
    public void deactivateAction(Holder<? extends ILastingAction<T>> action, boolean ignoreCooldown, boolean fullCooldown) {
        if (activeTimers.containsKey(action)) {
            int leftTime = activeTimers.getInt(action);
            int duration = expectedDurations.getInt(action);
            var event = FactionEventFactory.fireActionDeactivatedEvent(player, action, leftTime, expectedCooldownTimes.getInt(action), ignoreCooldown, fullCooldown);
            int cooldown = event.getCooldown();
            if (!event.ignoreCooldown() && !cooldownTimers.containsKey(action)) {
                if (!event.fullCooldown()) {
                    cooldown -= (int) (cooldown * (leftTime / (float) duration / 2f));
                } else {
                    expectedCooldownTimes.put(action, cooldown);
                }
                //Entries should be at least 1
                cooldownTimers.put(action, Math.max(cooldown, 1));
                activeTimers.put(action, 1);
            }
            activeTimers.removeInt(action);
            expectedDurations.removeInt(action);
            action.value().onDeactivated(player);
            sync();
        }
    }

@Override
    public final IActionResult canUse(T player) {
        if (!isEnabled()) {
            return IActionResult.DISABLED_CONFIG;
        }
        if (IFaction.is(player.getFaction(), this.factions())) {
            return canBeUsedBy(player);
        } else {
            return IActionResult.DISALLOWED_FACTION;
        }

    }

@Override
    public IActionResult onActivated(T player, ActivationContext context) {
        if (IFaction.is(player.getFaction(), this.factions())) {
            return activateServer(player, context);
        } else {
            throw new IllegalArgumentException("Faction player is not allowed to use action");
        }
    }

@Override
    public IActionResult activateServer(final IVampirePlayer vampire, ActivationContext context) {
        if (vampire.asEntity().level().environmentAttributes().getValue(EnvironmentAttributes.WATER_EVAPORATES, vampire.asEntity().position())) {
            return IActionResult.SUCCESS;
        }
        freezeEntities(vampire);
        freezeBlocks(vampire);
        Player player = vampire.asEntity();
        ModParticles.spawnParticlesServer(player.level(), ParticleTypes.SNOWFLAKE, player.getX(), player.getY(), player.getZ(), 300, 7, 4, 7, 0);
        return IActionResult.SUCCESS;
    }

protected void freezeEntities(IVampirePlayer vampire) {
        Player player = vampire.asEntity();
        IFactionPredicate build = IFactionPredicate.builder(ModFactions.VAMPIRE).ignoreDisguise().and(EntitySelector.NO_SPECTATORS).build();
        List<LivingEntity> l = player.level().getEntitiesOfClass(LivingEntity.class, player.getBoundingBox().inflate(7, 4, 7), build);
        for (LivingEntity entity : l) {
            if (player.equals(entity)) continue;
            entity.level().playSound(null, entity.getX(), entity.getY(), entity.getZ(), ModSounds.FREEZE.get(), SoundSource.PLAYERS, 1f, 1f);
            ModParticles.spawnParticlesServer(player.level(), ParticleTypes.SNOWFLAKE, entity.getX(), entity.getY(), entity.getZ(), 20, 1, 1, 1, 0);

            if (!entity.canFreeze()) continue;

            int dur = ModConfig.balance().vaFreezeDuration.get() * 20;
            if (vampire.getRefinementHandler().isRefinementEquipped(ModRefinements.FREEZE_DURATION)) {
                dur *= ModConfig.balance().vrFreezeDurationMod.get();
            }
            entity.addEffect(new MobEffectInstance(ModEffects.FREEZE, dur));
            entity.setSharedFlagOnFire(false);
        }
    }

protected void freezeBlocks(IVampirePlayer vampire) {
        Player player = vampire.asEntity();
        Level level = player.level();
        for (int i = -7; i < 7; i++) {
            for (int j = -7; j < 7; j++) {
                for (int k = -4; k < 4; k++) {
                    BlockPos pos = new BlockPos(player.getBlockX() + i, player.getBlockY() + j, player.getBlockZ() + k);
                    BlockState blockState = level.getBlockState(pos);

                    if (blockState.hasProperty(BlockStateProperties.LIT) && blockState.getValue(BlockStateProperties.LIT)) {
                        level.setBlock(pos, blockState.setValue(BlockStateProperties.LIT, false), 3);
                    } else if (blockState.getBlock() instanceof BaseFireBlock s) {
                        level.destroyBlock(pos, false);
                    }
                }
            }
        }
    }

@Override
    public int getCooldown(IVampirePlayer player) {
        return ModConfig.balance().vaFreezeCooldown.get() * 20;
    }

@Override
    protected boolean doBlockInteraction(BlockPos pos, double squareDistToBlock) {
        ServerPlayerGameMode manager = drone.getFakePlayer().gameMode;
        ServerPlayerGameModeAccess access = (ServerPlayerGameModeAccess) manager;
        if (!access.isDestroyingBlock() || !access.hasDelayedDestroy()) { //is not destroying and is not acknowledged.
            BlockState blockState = worldCache.getBlockState(pos);
            if (!ignoreBlock(blockState) && isBlockValidForFilter(worldCache, pos, drone, progWidget)) {
                if (blockState.getDestroySpeed(drone.getDroneLevel(), pos) < 0) {
                    addToBlacklist(pos);
                    drone.getDebugger().addEntry("pneumaticcraft.gui.progWidget.dig.debug.cantDigBlock", pos);
                    drone.setDugBlock(null);
                    return false;
                }
                Direction face = progWidget instanceof ProgWidgetDig dig ? dig.getDigSide() : Direction.UP;
                PlayerInteractEvent.LeftClickBlock event = CommonHooks.onLeftClickBlock(drone.getFakePlayer(), pos, face, ServerboundPlayerActionPacket.Action.START_DESTROY_BLOCK);
                if (!event.isCanceled()) {
                    int limit = drone.getDroneLevel().getMaxBuildHeight();
                    manager.handleBlockBreakAction(pos, ServerboundPlayerActionPacket.Action.START_DESTROY_BLOCK, face, limit, 0);
                    manager.handleBlockBreakAction(pos, ServerboundPlayerActionPacket.Action.STOP_DESTROY_BLOCK, face, limit, 1);
                    drone.setDugBlock(pos, face);
                    return true;
                }
            }
            drone.setDugBlock(null);
            return false;
        } else {
            return true;
        }
    }

@Override
    public boolean canContinueToUse() {
        if (aborted) return false;
        if (searching) {
            if (!sorter.isDone()) return true; // wait until the area is sorted according to the given ordering

            boolean firstRun = true;
            int searchedBlocks = 0; // tracks the number of inspected blocks; stop searching when MAX_LOOKUPS_PER_SEARCH is reached
            while (curPos == null && curY != lastSuccessfulY && order != Ordering.CLOSEST || firstRun) {
                firstRun = false;
                List<BlockPos> inspectedPositions = new ArrayList<>();
                while (!shouldAbort() && searchIndex < area.size()) {
                    BlockPos pos = area.get(searchIndex);
                    searchIndex++;
                    if (isYValid(pos.getY()) && !blacklist.contains(pos) && (!respectClaims() || !DroneClaimManager.getInstance(drone.getDroneLevel()).isClaimed(pos))) {
                        if (!drone.getDebugger().getDebuggingPlayers().isEmpty()) inspectedPositions.add(pos);
                        if (isValidPosition(pos)) {
                            curPos = pos;
                            if (moveToPositions()) {
                                if (tryMoveToBlock(pos)) {
                                    return true;
                                }
                                if (drone.getPathNavigator().isGoingToTeleport()) {
                                    return movedToBlockOK(pos);
                                } else {
                                    drone.getDebugger().addEntry("pneumaticcraft.gui.progWidget.general.debug.cantNavigate", pos);
                                }
                            } else {
                                searching = false;
                                totalActions++;
                                return true;
                            }
                        }
                        searchedBlocks++;
                    }
                    if (searchedBlocks >= MAX_LOOKUPS_PER_SEARCH) {
                        indicateToListeningPlayers(inspectedPositions);
                        return true;
                    }
                }
                indicateToListeningPlayers(inspectedPositions);
                if (curPos == null) updateY();
            }
            if (!shouldAbort()) addEndingDebugEntry();
            return false;
        } else {
            // found a block to interact with; we're now either moving to it, or we've arrived there
            // curPos *should* always be non-null here, but just to be defensive...
            if (curPos != null) {
                if (respectClaims()) {
                    DroneClaimManager.getInstance(drone.getDroneLevel()).claim(curPos);
                }
                double distSq = drone.getDronePos().distanceToSqr(Vec3.atCenterOf(curPos));
                if (!moveToPositions() || distSq < (moveIntoBlock() ? 1 : 4)) {  // 1 or 2 blocks
                    return doBlockInteraction(curPos, distSq);
                }
            }
            // if we end up here, we're either still travelling (return true) or have nowhere to go (return false)
            return !drone.getPathNavigator().hasNoPath();
        }
    }

private void tickFakePlayer() {
        FakePlayer fp = getFakePlayer();
        fp.setPos(position());
        fp.tick();
        if (getDugBlock() != null) {
            fp.lookAt(EntityAnchorArgument.Anchor.EYES, Vec3.atCenterOf(getDugBlock()));
        }
        if (isAlive()) {
            for (int i = 0; i < 4; i++) {
                fp.gameMode.tick();
            }
        }
    }

@Override
    public BlockPos getDugBlock() {
        BlockPos pos = entityData.get(DUG_POS);
        return pos.equals(BlockPos.ZERO) ? null : pos;
    }

@Override
    public void setDugBlock(BlockPos pos) {
        entityData.set(DUG_POS, pos == null ? BlockPos.ZERO : pos);
        if (pos == null) {
            digSourcePos = null;
        }
    }

@Override
    public void setDugBlock(@NotNull BlockPos pos, Direction side) {
        setDugBlock(pos);
        digSourcePos = pos.relative(side);
    }

@Override
    public void die(DamageSource damageSource) {
        super.die(damageSource);

        for (Entity e : getPassengers()) {
            if (e instanceof Mob mob) {
                mob.setNoAi(carriedEntityAIdisabled);
            }
        }

        restoreFluidBlocks(false);

        if (level() instanceof ServerLevel serverLevel) {
            if (chunkLoader != null) {
                chunkLoader.unloadAll(serverLevel);
            }

            if (getDugBlock() != null) {
                // stop any in-progress digging - 3rd & 4th parameters are unimportant here
                getFakePlayer().gameMode.handleBlockBreakAction(getDugBlock(), ServerboundPlayerActionPacket.Action.ABORT_DESTROY_BLOCK, Direction.UP, 0, 0);
            }
        }

        if (shouldDropAsItem()) {
            ItemStack stack = new ItemStack(getDroneItem());
            writeToItemStack(stack);
            spawnAtLocation(stack, 0);
            if (!level().isClientSide) {
                reportDroneDeath(getOwner(), damageSource);
            }
        }

        setCustomName(Component.empty());  // keep other mods (like CoFH Core) quiet about death message broadcasts
    }
